/// <summary>
/// Handles DMF INSERT operations.
/// </summary>
public boolean insertEntityDataSource(
    DataEntityRuntimeContext            _entityCtx,
    DataEntityDataSourceRuntimeContext  _dataSourceCtx)
{
    this.resolveRecIds(_dataSourceCtx);
    return super(_entityCtx, _dataSourceCtx);
}

/// <summary>
/// Handles DMF UPDATE operations, allowing updates to existing date-effective records.
/// </summary>
public boolean updateEntityDataSource(
    DataEntityRuntimeContext            _entityCtx,
    DataEntityDataSourceRuntimeContext  _dataSourceCtx)
{
    this.resolveRecIds(_dataSourceCtx);
    return super(_entityCtx, _dataSourceCtx);
}

    /// <summary>
    /// Prepares the buffer and resolves RecIds before data is mapped to the target.
    /// </summary>
    public void mapEntityToDataSource(
        DataEntityRuntimeContext            _entityCtx,
        DataEntityDataSourceRuntimeContext  _dataSourceCtx)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METTaxRegistrationEntity, TaxRegistration))
        {
            TaxRegistration taxReg = _dataSourceCtx.getBuffer();
            
            // Set mode to Correction to allow updating the 'Expiration' (ValidTo) column
            // without triggering SQL Change Tracking or chronological validation errors.
            taxReg.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);
        }

        super(_entityCtx, _dataSourceCtx);
        this.resolveRecIds(_dataSourceCtx);
    }

    /// <summary>
    /// Core logic to resolve internal RecIds
    /// </summary>
    private void resolveRecIds(DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        if (_dataSourceCtx.name() == dataEntityDataSourceStr(METTaxRegistrationEntity, TaxRegistration))
        {
            TaxRegistration taxReg = _dataSourceCtx.getBuffer();
            
            // Re-apply correction mode to ensure the buffer is in the correct state during resolution.
            taxReg.validTimeStateUpdateMode(ValidTimeStateUpdate::Correction);

            // 1. Resolve DirPartyLocation from LocationId or PartyNumber
            if (this.LocationId || this.PartyNumber)
            {
                DirPartyLocationRecId resolvedLocation = METTaxRegistrationEntity::resolveDirPartyLocation(
                    this.LocationId,
                    this.PartyNumber);

                if (resolvedLocation)
                {
                    this.DirPartyLocation   = resolvedLocation;
                    taxReg.DirPartyLocation = resolvedLocation;
                }
            }

            // 2. Resolve TaxRegistrationTypeApplicabilityRule from Type and Country
            if (this.TaxRegstrationType && this.CountryRegionId)
            {
                RecId resolvedRule = METTaxRegistrationEntity::resolveApplicabilityRule(
                    this.TaxRegstrationType,
                    this.CountryRegionId);

                if (resolvedRule)
                {
                    this.TaxRegistrationTypeApplicabilityRule   = resolvedRule;
                    taxReg.TaxRegistrationTypeApplicabilityRule = resolvedRule;
                }
            }
        }
    }

    /// <summary>
    /// Static helper to resolve DirPartyLocation.
    /// </summary>
    private static DirPartyLocationRecId resolveDirPartyLocation(str _locationId, str _partyNumber)
    {
        DirPartyLocationRecId   ret;
        LogisticsLocation       logisticsLocation;
        DirPartyLocation        dirPartyLocation;
        DirPartyTable           dirPartyTable;

        if (_locationId)
        {
            select firstonly RecId from logisticsLocation
                where logisticsLocation.LocationId == _locationId;

            if (logisticsLocation.RecId)
            {
                select firstonly RecId from dirPartyLocation
                    where dirPartyLocation.Location      == logisticsLocation.RecId
                       && dirPartyLocation.IsPostalAddress == NoYes::Yes;

                ret = dirPartyLocation.RecId;
            }
        }

        if (!ret && _partyNumber)
        {
            select firstonly RecId from dirPartyTable
                where dirPartyTable.PartyNumber == _partyNumber;

            if (dirPartyTable.RecId)
            {
                select firstonly RecId from dirPartyLocation
                    where dirPartyLocation.Party          == dirPartyTable.RecId
                       && dirPartyLocation.IsPostalAddress == NoYes::Yes;

                ret = dirPartyLocation.RecId;
            }
        }

        return ret;
    }

    /// <summary>
    /// Static helper to resolve Applicability Rule RecId.
    /// </summary>
    private static RecId resolveApplicabilityRule(str _taxRegTypeStr, LogisticsAddressCountryRegionId _countryId)
    {
        TaxRegistrationTypeApplicabilityRule    rule;
        TaxRegistrationType                     taxRegType;

        if (!_taxRegTypeStr || !_countryId)
        {
            return 0;
        }

        select firstonly RecId from rule
            where rule.CountryRegionId == _countryId
        exists join taxRegType
            where taxRegType.RecId              == rule.TaxRegistrationType
               && taxRegType.TaxRegstrationType == _taxRegTypeStr;

        return rule.RecId;
    }
